package io.github.omeryol.akisgesture.feedback.animation
import android.graphics.*
import io.github.omeryol.akisgesture.overlay.Edge
import kotlin.math.sin
class GlassRefractionModule:NaturalAnimationModule{private val p=Paint(Paint.ANTI_ALIAS_FLAG).apply{style=Paint.Style.FILL};override fun draw(f:AnimationFrame){val d=(6f+f.stretch*(.68f+f.surfaceTension*.20f)).coerceAtMost(220f*f.size);val c=when(f.edge){Edge.LEFT->d to f.touch;Edge.RIGHT->f.width-d to f.touch;Edge.BOTTOM->f.touch to f.height-d};val r=(12f+f.progress*(82f+f.surfaceTension*23f))*f.size;val wobble=sin(f.time*(1.15+f.damping*1.1)).toFloat()*r*(.025f+f.viscosity*.035f);val oval=RectF(c.first-r*1.35f,c.second-r*.72f+wobble,c.first+r*1.35f,c.second+r*.72f+wobble);p.shader=RadialGradient(c.first-r*.35f,c.second-r*.3f,r*1.8f,intArrayOf(alpha(lighten(f.color,.72f),(165*f.opacity).toInt()),alpha(f.color,(90*f.opacity).toInt()),alpha(darken(f.color,.55f),(35*f.opacity).toInt())),floatArrayOf(0f,.48f,1f),Shader.TileMode.CLAMP);f.canvas.drawOval(oval,p);p.shader=null;p.style=Paint.Style.STROKE;p.strokeWidth=(2.2f+f.surfaceTension)*f.size;for(i in 0..2){p.color=alpha(when(i){0->lighten(f.color,.55f);1->f.color;else->darken(f.color,.28f)},(90*f.opacity).toInt());val off=(i-1)*(4f+f.surfaceTension*2f)*f.size;f.canvas.drawOval(RectF(oval.left+off,oval.top-off,oval.right+off,oval.bottom-off),p)};p.style=Paint.Style.FILL}}
